	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void projectedCompatibilityDeclinesReplacedDescendantUntilRefresh(boolean fatal) {
		BindingSetAssignment values = assignment(List.of(row("local")));
		values.setDeclaredBindingNames(Set.of("local"));
		Join body = new Join(values, new SingletonSet());
		Projection projection = new Projection(body,
				new ProjectionElemList(new ProjectionElem("local", "g")), false);
		QueryEvaluationUtility.withPreparedQuerySafetySnapshot(projection, PreparedValuesSnapshot::newPreparation,
				prepared -> {
					var input = QueryAlgebraBindingAnalysis.withBindingValues(prepared, EmptyBindingSet.getInstance());
					var names = QueryEvaluationUtility.preparedOptionalInputNames(prepared);
					var initial = QueryAlgebraBindingAnalysis.withInputContextAndPossibleInputs(prepared,
							input.rootContext(), Set.of(), names);
					assertNotNull(initial.semanticInvocationTransition(projection));
					body.setRightArg(fatal ? new Service(Var.of("endpoint", RDF4J.NIL), new SingletonSet(), "",
							Map.of(), null, false) : new SingletonSet());
					var stale = QueryAlgebraBindingAnalysis.withInputContextAndPossibleInputs(prepared,
							input.rootContext(), Set.of(), names);
					assertNull(stale.semanticInvocationTransition(projection));
					QueryEvaluationUtility.refreshQuerySafetySnapshot(projection);
					var refreshed = QueryAlgebraBindingAnalysis.withInputContextAndPossibleInputs(prepared,
							input.rootContext(), Set.of(), QueryEvaluationUtility.preparedOptionalInputNames(prepared));
					if (fatal) {
						assertNull(refreshed.semanticInvocationTransition(projection));
					} else {
						assertNotNull(refreshed.semanticInvocationTransition(projection));
					}
					return null;
				});
	}

	@Test
	void ownerFilterCertificateRetainsRealBindingsSharingAConstantName() {
		var vf = SimpleValueFactory.getInstance();
		for (boolean subject : List.of(true, false)) {
			Var constant = Var.of("shared", vf.createIRI("urn:certificate:p"), true, true);
			StatementPattern pattern = subject
					? new StatementPattern(Var.of("shared"), constant, Var.of("other"))
					: new StatementPattern(Var.of("other"), constant, Var.of("shared"));
			Filter filter = ownerFilter(assignment(List.of(row("t"))), "shared");
			Join owner = new Join(pattern, filter);
			QueryEvaluationUtility.withPreparedQuerySafetySnapshot(owner, PreparedValuesSnapshot::newPreparation,
					prepared -> {
						var analysis = QueryAlgebraBindingAnalysis.withBindingValues(prepared,
								EmptyBindingSet.getInstance());
						assertEquals(Set.of("shared", "other"), analysis.outputFacts(pattern).possibleOutputs());
						var scope = QueryEvaluationUtility.preparedFilterScope(prepared);
						assertNotNull(scope, "the real subject/object occurrence is an output");
						assertEquals(Set.of("shared", "other", "t"), scope.bindingNames());
						assertEquals(Set.of("shared", "t"), scope.conditionReads(filter));
						assertTrue(scope.conditionInputsAvailable(filter, Set.of("t"),
								(join, name) -> join == owner && name.equals("shared")));
						assertTrue(scope.permitsCorrelation(owner, Set.of("shared", "other", "t")));
						return null;
					});
		}
	}

	@Test
	void constantOccurrenceDoesNotShadowTheFartherFilterOwner() {
		var vf = SimpleValueFactory.getInstance();
		StatementPattern source = new StatementPattern(Var.of("e"),
				Var.of("predicate", vf.createIRI("urn:certificate:p"), true, true), Var.of("x"));
		StatementPattern guard = new StatementPattern(Var.of("e"),
				Var.of("x", vf.createIRI("urn:certificate:q"), true, true),
				Var.of("tag", vf.createIRI("urn:certificate:tag"), true, true));
		Filter filter = ownerFilter(assignment(List.of(row("t"))), "x");
		Join nearer = new Join(guard, filter);
		Join owner = new Join(source, nearer);
		QueryEvaluationUtility.withPreparedQuerySafetySnapshot(owner, PreparedValuesSnapshot::newPreparation,
				prepared -> {
					var scope = QueryEvaluationUtility.preparedFilterScope(prepared);
					assertNotNull(scope);
					var initial = QueryAlgebraBindingAnalysis.withBindingValues(prepared,
							EmptyBindingSet.getInstance());
					var analysis = QueryAlgebraBindingAnalysis.withInputContextAndPossibleInputs(prepared,
							initial.rootContext(), Set.of(),
							QueryEvaluationUtility.preparedOptionalInputNames(prepared));
					var valuesScope = QueryEvaluationUtility.preparedValuesScope(prepared, analysis);
					assertTrue(valuesScope.complete());
					assertTrue(valuesScope.observerReceives(filter, "x"));
					assertTrue(valuesScope.observerReceives(filter, "t"));
					assertEquals(Set.of("e", "x", "t"), scope.bindingNames());
					assertEquals(Set.of("x", "t"), scope.conditionReads(filter));
					assertTrue(scope.conditionInputsAvailable(filter, Set.of("t"),
							(join, name) -> join == owner && name.equals("x")));
					assertFalse(scope.conditionInputsAvailable(filter, Set.of("t"),
							(join, name) -> join == nearer));
					return null;
				});
	}

