			assertNull(QueryEvaluationUtility.preparedFilterScope(unknownContext));

			StatementPattern alias = graphPattern(graphScope, Var.of("g"), Var.of("g"));
			Join aliasedContext = new Join(alias, ownerFilter(assignment(List.of(row("t"))), "x"));
			var aliased = QueryEvaluationUtility.preparedFilterScope(aliasedContext);
